def test_succeeds_first_time():
    @retry(times=3, sleep=lambda s: None)
    def ok():
        """Docstring"""
        return 42

    assert ok() == 42
    assert ok.__name__ == "ok"
    assert ok.__doc__ == "Docstring"


def test_reraises_after_last_attempt():
    calls = []

    @retry(times=3, exceptions=(ConnectionError,), sleep=lambda s: None)
    def flaky():
        calls.append(1)
        raise ConnectionError("down")

    with pytest.raises(ConnectionError) as excinfo:
        flaky()
    assert "down" in str(excinfo.value)
    assert len(calls) == 3


def test_invalid_times():
    with pytest.raises(ValueError):
        @retry(times=0)
        def f():
            pass

    with pytest.raises(ValueError):
        @retry(times=-1)
        def f():
            pass


def test_unlisted_exception_propagates_immediately():
    sleep_calls = []
    attempts = []

    @retry(times=3, exceptions=(ConnectionError,), sleep=sleep_calls.append)
    def err():
        attempts.append(1)
        raise ValueError("unexpected")

    with pytest.raises(ValueError):
        err()

    assert len(attempts) == 1
    assert len(sleep_calls) == 0


def test_delays_behavior():
    sleeps = []

    @retry(times=4, delays=[0.1, 0.5], sleep=sleeps.append)
    def flaky():
        raise ConnectionError()

    with pytest.raises(ConnectionError):
        flaky()

    # attempts = 4, so retries = 3 (between attempt 1 & 2, 2 & 3, 3 & 4)
    # delays=[0.1, 0.5]:
    # attempt 1 fails -> wait delays[0] (0.1)
    # attempt 2 fails -> wait delays[1] (0.5)
    # attempt 3 fails -> wait delays[-1] (0.5)
    # attempt 4 fails -> no sleep (final failed attempt)
    assert sleeps == [0.1, 0.5, 0.5]


def test_delays_none():
    sleeps = []

    @retry(times=3, delays=None, sleep=sleeps.append)
    def flaky():
        raise ConnectionError()

    with pytest.raises(ConnectionError):
        flaky()

    assert sleeps == [1, 1]
